package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class WordUtils_ESTest_test28 extends WordUtils_ESTest_scaffolding {

    /**
     * capitalizeFully lower-cases every character and then title-cases the first
     * character of each word. Here the delimiters array contains only NUL chars
     * ('�'), none of which appear in the input, so the whole string is treated
     * as a single word: the result is simply the lower-cased input (its leading ';'
     * has no case, so nothing is upper-cased).
     */
    @Test(timeout = 4000)
    public void capitalizeFullyWithUnusedDelimitersJustLowerCasesInput() throws Throwable {
        char[] delimiters = new char[2]; // {'�', '�'} - not present in the input

        String result = WordUtils.capitalizeFully(";)(5b_Sh4o|A8@", delimiters);

        assertEquals(";)(5b_sh4o|a8@", result);
    }
}
